"""Compile and validate the general FP32 coverage shaders."""
from pathlib import Path
import subprocess
SHADERS = ['convolution_nd', 'lstm_cell', 'lstm_cell_backward', 'random_fill', 'dropout', 'dropout_backward', 'indexed', 'embedding_heads', 'embedding_links', 'embedding_gradient', 'native_copy_strided', 'sort_axis', 'scan_axis', 'flip', 'fft_prepare', 'fft_butterfly', 'fft_direct', 'fft_finish', 'complex_unary', 'lu_factor', 'lu_solve', 'sdpa_training', 'triangular', 'embedding_bag_validate', 'embedding_bag_meta', 'embedding_bag', 'embedding_bag_backward', 'pool3d_general', 'resample_axis', 'pad_axis', 'grid_sample_general', 'extrema_fp32', 'sparse_count', 'sparse_pack', 'sparse_dense', 'integer_fill', 'lu_validate', 'sparse_coalesce_order', 'sparse_coalesce_scan', 'sparse_coalesce_values', 'sparse_validate', 'integer_binary', 'integer_reduce', 'complex_binary', 'sparse_shape', 'bool_to_float', 'random_integer', 'device_copy', 'comparison', 'copy_storage', 'sequence_factory', 'randperm', 'reduction_general', 'svd_jacobi', 'integer_bitwise', 'advanced_index', 'nonzero_scan', 'nonzero_write', 'nll_validate', 'pointwise_math', 'native_pack_short', 'where_typed', 'loss_binary', 'loss_unary', 'loss_mutate', 'cholesky_factor', 'cholesky_solve', 'complex_magnitude', 'extrema_general', 'indexed_integer', 'lu_permutation', 'scan_general', 'pointwise_binary', 'sort_integer', 'integer_math', 'special_gamma', 'unique_rows', 'eigh_jacobi', 'qr_factor', 'qr_apply', 'integer_matmul', 'diffusion_unary', 'reduce_axes', 'searchsorted', 'frexp', 'layer_norm', 'layer_norm_backward_input', 'layer_norm_backward_param', 'mode_sorted', 'special_functions', 'incomplete_gamma', 'image_columns', 'unfold_backward_general', 'quantile_ranks', 'segment_reduce_general', 'margin_losses', 'hash_tensor_general', 'bincount_general', 'triangular_indices', 'fractional_pool_general', 'iteration_fp32', 'ctc_loss_general', 'ldl_factor_general', 'ldl_solve_general']
if __name__ == '__main__':
    root = Path(__file__).resolve().parents[1] / 'csrc/shaders'
    for name in SHADERS:
        target = root / f'{name}.spv'
        subprocess.run(['glslangValidator', '-V', str(root / f'{name}.comp'), '-o', str(target)], check=True)
        subprocess.run(['spirv-val', '--target-env', 'vulkan1.0', str(target)], check=True)
